package playability

import (
	"errors"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"strings"
)

// writeDV81 writes a Dolby Vision profile 8.1 stream to out: an HDR10 base encoded by libx265,
// an RPU generated by dovi_tool and injected into every picture, and the result encoded again
// by libx265 with -dolbyvision 1, which carries each picture's RPU and writes the DOVI
// configuration record. The recipe of internal/engine's dynamic-HDR fixtures, smaller.
func writeDV81(ffmpeg, dir, out string) error {
	dovi := envOr("HOLDFAST_DOVI_TOOL", "dovi_tool")
	if _, err := exec.LookPath(dovi); err != nil {
		return fmt.Errorf("::error:: %q not found - the Dolby Vision fixture requires the pinned dovi_tool "+
			"(set HOLDFAST_DOVI_TOOL): %w", dovi, err)
	}
	base, rpu, inj, gen := filepath.Join(dir, "dv-base.hevc"), filepath.Join(dir, "dv-rpu.bin"),
		filepath.Join(dir, "dv-inj.hevc"), filepath.Join(dir, "dv-gen.json")
	gop := "log-level=error:keyint=24:min-keyint=24:scenecut=0:open-gop=1:bframes=4:" + hdr10Params
	if err := run(ffmpeg, "-f", "lavfi", "-i", "testsrc2=duration=2:size=160x128:rate=24", "-pix_fmt", "yuv420p10le",
		"-c:v", "libx265", "-preset", "ultrafast", "-x265-params", gop, base); err != nil {
		return err
	}
	if err := os.WriteFile(gen, []byte(`{"cm_version":"V40","length":48,"level6":{"max_display_mastering_luminance":1000,`+
		`"min_display_mastering_luminance":1,"max_content_light_level":1000,"max_frame_average_light_level":400}}`), 0o644); err != nil {
		return err
	}
	for _, args := range [][]string{{"generate", "-j", gen, "-o", rpu}, {"inject-rpu", "-i", base, "--rpu-in", rpu, "-o", inj}} {
		if b, err := exec.Command(dovi, args...).CombinedOutput(); err != nil {
			return fmt.Errorf("dovi_tool %v: %w\n%s", args, err, b)
		}
	}
	return run(ffmpeg, "-f", "hevc", "-framerate", "24", "-i", inj, "-c:v", "libx265", "-preset", "ultrafast",
		"-dolbyvision", "1", "-pix_fmt", "yuv420p10le", "-x265-params", gop+":vbv-maxrate=20000:vbv-bufsize=20000", out)
}

// mislabel writes to out, in the muxer format named, a copy of src whose RASL pictures (NAL
// types 8 and 9) are relabelled RADL (6 and 7). Every picture keeps its bytes and its
// references, so a linear decode decodes the same frames; a decoder that STARTS at a keyframe
// would drop its RASL pictures, and decodes its RADL pictures from that keyframe alone, so the
// relabelled ones reference a picture it never saw. Ported from the fixture of #204
// (playabilitytest.Mislabel): the NAL headers are rewritten in a copy of src's bytes at the
// offsets ffprobe reports for its packets, and the copy is remuxed so the container is its own.
func mislabel(c Checker, src, out, format string) error {
	data, err := os.ReadFile(src)
	if err != nil {
		return err
	}
	listing, err := exec.Command(c.FFprobe, "-v", "error", "-select_streams", "v:0",
		"-show_entries", "packet=pos,size", "-of", "default=nw=1", "--", src).Output()
	if err != nil {
		return fmt.Errorf("list packets: %w", err)
	}
	var size, pos int64 = -1, -1
	n := 0
	for _, line := range strings.Split(string(listing), "\n") {
		k, v, ok := strings.Cut(strings.TrimSpace(line), "=")
		if !ok {
			continue
		}
		x, err := strconv.ParseInt(v, 10, 64)
		if err != nil {
			return fmt.Errorf("packet line %q: %w", line, err)
		}
		switch k {
		case "size":
			size = x
		case "pos":
			pos = x
		}
		if size < 0 || pos < 0 {
			continue
		}
		m, err := relabelPacket(data, pos, size)
		if err != nil {
			return err
		}
		n += m
		size, pos = -1, -1
	}
	if n == 0 {
		return errors.New("no RASL picture was relabelled: the source has none")
	}
	edited := out + ".relabelled"
	if err := os.WriteFile(edited, data, 0o644); err != nil {
		return err
	}
	return run(c.FFmpeg, "-i", edited, "-map", "0", "-c", "copy", "-f", format, out)
}

// relabelPacket finds the packet's payload - at pos in an MP4, or after the block header in
// Matroska (a track-number vint, a 2-byte timecode and a flags byte) - as the offset at which
// the 4-byte NAL lengths chain exactly to size, and relabels its RASL units.
func relabelPacket(data []byte, pos, size int64) (int, error) {
	if pos < 0 || pos >= int64(len(data)) {
		return 0, fmt.Errorf("packet at %d lies outside the file", pos)
	}
	starts := []int64{pos}
	if b := data[pos]; b != 0 {
		vint := int64(1)
		for mask := byte(0x80); b&mask == 0; mask >>= 1 {
			vint++
		}
		starts = append(starts, pos+vint+3)
	}
	for _, start := range starts {
		if chains(data, start, start+size) {
			return relabelNALs(data, start, start+size), nil
		}
	}
	return 0, fmt.Errorf("packet at %d (+%d): no length-prefixed NAL units found", pos, size)
}

// chains reports whether data[p:end] is exactly a run of 4-byte length-prefixed NAL units.
func chains(data []byte, p, end int64) bool {
	if end > int64(len(data)) || p >= end {
		return false
	}
	for p < end {
		if p+5 > end {
			return false
		}
		l := int64(data[p])<<24 | int64(data[p+1])<<16 | int64(data[p+2])<<8 | int64(data[p+3])
		if l < 2 || p+4+l > end {
			return false
		}
		p += 4 + l
	}
	return true
}

func relabelNALs(data []byte, p, end int64) int {
	n := 0
	for p < end {
		l := int64(data[p])<<24 | int64(data[p+1])<<16 | int64(data[p+2])<<8 | int64(data[p+3])
		h := p + 4
		if t := (data[h] >> 1) & 0x3f; t == nalRASLN || t == nalRASLR {
			data[h] = (data[h] & 0x81) | (t-2)<<1
			n++
		}
		p = h + l
	}
	return n
}
